<html lang="en" data-theme="auto" data-active-theme="light">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{ $project->exists ? 'Edit' : 'Add' }} Project | Admin</title><script>(()=>{let t='auto';try{t=localStorage.getItem('zyuru-theme')||'auto'}catch{}const d=matchMedia('(prefers-color-scheme: dark)').matches;const a=t==='auto'?(d?'dark':'light'):t;document.documentElement.dataset.theme=t;document.documentElement.dataset.activeTheme=a;document.documentElement.style.colorScheme=a})();</script><link rel="stylesheet" href="{{ asset('css/style.css') }}"><link rel="stylesheet" href="{{ asset('css/admin.css') }}"><link rel="stylesheet" href="{{ asset('css/admin-polish.css') }}"><link rel="stylesheet" href="{{ asset('css/projects.css') }}"></head>
