@foreach([['title','Project title','text'],['short_description','Short description','text'],['full_description','Full description','textarea'],['github_url','GitHub repository URL','url']] as [$field,$label,$type])<div class="form-field"><label for="{{ $field }}">{{ $label }}</label>@if($type==='textarea')<textarea id="{{ $field }}" name="{{ $field }}" required>{{ old($field,$project->$field) }}</textarea>@else<input id="{{ $field }}" name="{{ $field }}" type="{{ $type }}" value="{{ old($field,$project->$field) }}" required maxlength="{{ $field==='title'?120:($field==='short_description'?300:2048) }}">@endif @error($field)<small class="field-error">{{ $message }}</small>@enderror</div>@endforeach
