<div class="form-field"><label for="logo">Project logo {{ $project->exists ? '(optional)' : '' }}</label>@if($project->logo_path)<img class="form-media-preview" src="{{ asset('storage/'.$project->logo_path) }}" alt="Current logo">@endif<input id="logo" name="logo" type="file" accept="image/jpeg,image/png,image/webp" {{ $project->exists?'':'required' }}><img class="form-media-preview" id="logoPreview" alt="Logo preview" hidden>@error('logo')<small class="field-error">{{ $message }}</small>@enderror</div>
<div class="form-field"><label for="preview">Project preview (image or MP4 video)</label>@if($project->preview_path)<p>Current preview: <a href="{{ asset('storage/'.$project->preview_path) }}" target="_blank" rel="noopener">Open</a></p><label><input type="checkbox" name="remove_preview" value="1"> Remove current preview</label>@endif<input id="preview" name="preview" type="file" accept="image/jpeg,image/png,image/webp,video/mp4"><div id="previewContainer"></div>@error('preview')<small class="field-error">{{ $message }}</small>@enderror</div>
<div class="form-actions"><button class="primary-button" type="submit">Save project</button><a class="ghost-button" href="{{ route('admin.dashboard',['section'=>'projects']) }}">Cancel</a></div></form></main></div><script>const root=document.documentElement,toggle=document.getElementById('themeToggle');toggle.addEventListener('click',()=>{const t=root.dataset.activeTheme==='light'?'dark':'light';try{localStorage.setItem('zyuru-theme',t)}catch{}root.dataset.theme=t;root.dataset.activeTheme=t;root.style.colorScheme=t});document.getElementById('logo').addEventListener('change',e=>previewImage(e.target,document.getElementById('logoPreview')));document.getElementById('preview').addEventListener('change',e=>{const f=e.target.files[0],box=document.getElementById('previewContainer');box.replaceChildren();if(!f)return;const u=URL.createObjectURL(f),el=document.createElement(f.type.startsWith('video/')?'video':'img');el.src=u;if(el.tagName==='VIDEO'){el.controls=true;el.playsInline=true}else el.alt='Preview';el.className='form-media-preview';box.append(el)});function previewImage(input,img){const f=input.files[0];if(f){img.src=URL.createObjectURL(f);img.hidden=false}}</script></body></html>
